import std.task as t
import std.gc as gc
async fn worker(a []int) int{t.yield()
gc.collect()
return a[0]}
fn main(){var a=[7]
let work=worker(a)
a[0]=9
print(await work,a[0],await work)}

import std.task as t
import std.gc as gc
async fn leaf() int{t.yield()
return 2}
async fn worker() int{var a=[5,7]
var r Result<[]int>=ok(a)
let n=await leaf()
gc.collect()
return unwrap(r)[0]+n}
fn main(){print(await worker())}

